def name_operands(region,address,operation):
 if region!='Station':return operation
 if address in FUNCTIONS:operation=operation.replace('(#692B)','(@ModelDescriptionState.RowCount)').replace('CALL #E154','CALL @D3D.PrintPreviewTextRows.Entry').replace('CALL #E124','CALL @D3D.CountPreviewTextRows.Entry')
 if address in (0x6916,0x6945):operation=operation.replace('(#6933)','(@ModelDescriptionState.TopRow)').replace('LD HL, #6952','LD HL, @Station.PrintModelDescription.Entry')
 return operation
